MODERN_STDLIB: dict[str, str] = {'Test.sol': '// SPDX-License-Identifier: MIT\n// DeFiCoser vendored minimal forge-std (offline, curated subset).\npragma solidity >=0.6.2 <0.9.0;\n\ninterface Vm {\n    // ── Role playing (Role -> Address -> Transaction) ──\n    function prank(address) external;\n    function startPrank(address) external;\n    function stopPrank() external;\n    function addr(uint256) external returns (address);\n    function label(address, string calldata) external;\n    function sign(uint256, bytes32) external returns (uint8, bytes32, bytes32);\n    function nonce(address) external returns (uint64);\n    // ── State manipulation ──\n    function deal(address, uint256) external;\n    function deal(address, address, uint256) external;\n    function warp(uint256) external;\n    function roll(uint256) external;\n    function skip(uint256) external;\n    function rewind(uint256) external;\n    function fee() external returns (uint256);\n    function store(address, bytes32, bytes32) external;\n    function load(address, bytes32) external returns (bytes32);\n    function etch(address, bytes calldata) external;\n    // ── Call control ──\n    function expectRevert() external;\n    function expectRevert(bytes4) external;\n    function expectRevert(bytes calldata) external;\n    function expectEmit() external;\n    function expectEmit(bool, bool, bool, bool) external;\n    function expectEmit(bool, bool, bool, bool, address) external;\n    function expectCall(address, bytes calldata) external;\n    function mockCall(address, bytes calldata, bytes calldata) external;\n    function clearMockedCalls() external;\n    // ── Miscellaneous ──\n    function assume(bool) external;\n    function getCode(string calldata) external returns (bytes memory);\n    function deployCode(string calldata) external returns (address);\n    function deployCode(string calldata, bytes calldata) external returns (address);\n    function toString(uint256) external returns (string memory);\n    function toString(int256) external returns (string memory);\n    function toString(address) external returns (string memory);\n    function toString(bytes32) external returns (string memory);\n    function toString(bool) external returns (string memory);\n}\n\n/// @dev Minimal Test base contract: vm cheatcodes + makeAddr + common assertions.\n///      A failed assertion reverts (forge records a failed test and collects the revert reason).\ncontract Test {\n    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);\n\n    // ── Address factory (same semantics as forge-std makeAddr) ──\n    function makeAddr(string memory name) public returns (address addr) {\n        uint256 privateKey = uint256(keccak256(abi.encodePacked(name)));\n        addr = vm.addr(privateKey);\n        vm.label(addr, name);\n    }\n\n    function makeAddrAndKey(string memory name)\n        public\n        returns (address addr, uint256 privateKey)\n    {\n        privateKey = uint256(keccak256(abi.encodePacked(name)));\n        addr = vm.addr(privateKey);\n        vm.label(addr, name);\n    }\n\n    // ── Assertions ──\n    function fail() internal virtual {\n        revert("fail()");\n    }\n\n    function fail(string memory err) internal virtual {\n        revert(err);\n    }\n\n    function assertTrue(bool data) internal virtual {\n        if (!data) revert("assertTrue failed");\n    }\n\n    function assertTrue(bool data, string memory err) internal virtual {\n        if (!data) revert(err);\n    }\n\n    function assertFalse(bool data) internal virtual {\n        if (data) revert("assertFalse failed");\n    }\n\n    function assertEq(bool a, bool b) internal virtual {\n        if (a != b) revert("assertEq(bool) failed");\n    }\n\n    function assertEq(uint256 a, uint256 b) internal virtual {\n        if (a != b) revert("assertEq(uint256) failed");\n    }\n\n    function assertEq(int256 a, int256 b) internal virtual {\n        if (a != b) revert("assertEq(int256) failed");\n    }\n\n    function assertEq(address a, address b) internal virtual {\n        if (a != b) revert("assertEq(address) failed");\n    }\n\n    function assertEq(bytes32 a, bytes32 b) internal virtual {\n        if (a != b) revert("assertEq(bytes32) failed");\n    }\n\n    function assertEq(string memory a, string memory b) internal virtual {\n        if (keccak256(bytes(a)) != keccak256(bytes(b))) revert("assertEq(string) failed");\n    }\n\n    function assertNotEq(bool a, bool b) internal virtual {\n        if (a == b) revert("assertNotEq(bool) failed");\n    }\n\n    function assertNotEq(uint256 a, uint256 b) internal virtual {\n        if (a == b) revert("assertNotEq(uint256) failed");\n    }\n\n    function assertNotEq(address a, address b) internal virtual {\n        if (a == b) revert("assertNotEq(address) failed");\n    }\n\n    function assertLt(uint256 a, uint256 b) internal virtual {\n        if (!(a < b)) revert("assertLt failed");\n    }\n\n    function assertGt(uint256 a, uint256 b) internal virtual {\n        if (!(a > b)) revert("assertGt failed");\n    }\n\n    function assertLe(uint256 a, uint256 b) internal virtual {\n        if (!(a <= b)) revert("assertLe failed");\n    }\n\n    function assertGe(uint256 a, uint256 b) internal virtual {\n        if (!(a >= b)) revert("assertGe failed");\n    }\n\n    function assertApproxEqAbs(uint256 a, uint256 b, uint256 maxDelta) internal virtual {\n        uint256 delta = a > b ? a - b : b - a;\n        if (delta > maxDelta) revert("assertApproxEqAbs failed");\n    }\n}\n', 'console.sol': '// SPDX-License-Identifier: MIT\n// DeFiCoser vendored minimal console (subset of forge-std console).\npragma solidity >=0.4.23;\n\nlibrary console {\n    address constant CONSOLE_ADDRESS = 0x000000000000000000636F6e736F6c652e6c6f67;\n\n    function _send(bytes memory payload) private view {\n        (bool ok, ) = CONSOLE_ADDRESS.staticcall(payload);\n        ok;\n    }\n\n    function log(string memory p0) internal view {\n        _send(abi.encodeWithSignature("log(string)", p0));\n    }\n\n    function log(uint256 p0) internal view {\n        _send(abi.encodeWithSignature("log(uint256)", p0));\n    }\n\n    function log(int256 p0) internal view {\n        _send(abi.encodeWithSignature("log(int256)", p0));\n    }\n\n    function log(address p0) internal view {\n        _send(abi.encodeWithSignature("log(address)", p0));\n    }\n\n    function log(bool p0) internal view {\n        _send(abi.encodeWithSignature("log(bool)", p0));\n    }\n\n    function log(bytes32 p0) internal view {\n        _send(abi.encodeWithSignature("log(bytes32)", p0));\n    }\n\n    function log(string memory p0, uint256 p1) internal view {\n        _send(abi.encodeWithSignature("log(string,uint256)", p0, p1));\n    }\n\n    function log(string memory p0, address p1) internal view {\n        _send(abi.encodeWithSignature("log(string,address)", p0, p1));\n    }\n\n    function log(string memory p0, string memory p1) internal view {\n        _send(abi.encodeWithSignature("log(string,string)", p0, p1));\n    }\n\n    function log(string memory p0, bool p1) internal view {\n        _send(abi.encodeWithSignature("log(string,bool)", p0, p1));\n    }\n}\n', 'console2.sol': '// SPDX-License-Identifier: MIT\n// DeFiCoser vendored minimal console2 (alias layer with the same implementation as console; \n// forge decodes calls with the same selectors on this address as console logs).\npragma solidity >=0.4.23;\n\nimport {console} from "./console.sol";\n\nlibrary console2 {\n    function log(string memory p0) internal view {\n        console.log(p0);\n    }\n\n    function log(uint256 p0) internal view {\n        console.log(p0);\n    }\n\n    function log(address p0) internal view {\n        console.log(p0);\n    }\n\n    function log(string memory p0, uint256 p1) internal view {\n        console.log(p0, p1);\n    }\n\n    function log(string memory p0, string memory p1) internal view {\n        console.log(p0, p1);\n    }\n}\n'}
