def stdlib_for_solc(solc_version: str) -> dict[str, str]:
    try:
        parts = tuple((int(p) for p in str(solc_version).split('.')[:3]))
    except ValueError:
        return MODERN_STDLIB
    return MODERN_STDLIB if parts >= (0, 6, 2) else LEGACY_STDLIB
